from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];SRC=ROOT/'research/20261114/loki/h3br';PUBLIC=ROOT/'results/research/loki/h3br'


def main():
    s=json.loads((PUBLIC/'summary.json').read_text());p=json.loads((SRC/'protocol.json').read_text());pre=json.loads((SRC/'preflight.json').read_text());export=json.loads((PUBLIC/'ledger-export.json').read_text());F,P,U=[s['continuation_calls'][k] for k in ['firstlex','posterior','uniform']];saving=100*(1-P/U);fullsaving=100*(1-s['policy_calls']['posterior']/s['policy_calls']['uniform']);lines=[];add=lambda text='':lines.append(text)
